      "id": "6232786373666254271",
      "title": "If you change your mindset, you have the ability to change your whole world.",
      "slug": "if-you-change-your-mindset-you-have",
      "published": "2024-05-14T10:44:00.000-07:00",
      "dateFormatted": "May 14, 2024",
      "monthYear": "May 2024",
